      /** Display text: 5rem, weight 700. The largest heading, for hero titles. */
      display: string;
      /** Heading 1: 3rem, weight 700. The page title. */
      h1: string;
      /** Heading 2: 2rem, weight 700. Major sections. */
      h2: string;
